var Paho=Paho||{};
Paho.MQTT=(function(){
"use strict";
var ERROR={OK:{code:0,text:"AMQJSC0000I OK."},CONNECT_TIMEOUT:{code:1,text:"AMQJSC0001E Connect timed out."},SUBSCRIBE_TIMEOUT:{code:2,text:"AMQJSC0002E Subscribe timed out."},UNSUBSCRIBE_TIMEOUT:{code:3,text:"AMQJSC0003E Unsubscribe timed out."},PING_TIMEOUT:{code:4,text:"AMQJSC0004E Ping timed out."},INTERNAL_ERROR:{code:5,text:"AMQJSC0005E Internal error. Error Message: {0}, Stack trace: {1}"},CONNACK_RETURNCODE:{code:6,text:"AMQJSC0006E Bad Connack return code:{0} {1}."},SOCKET_ERROR:{code:7,text:"AMQJSC0007E Socket error:{0}."},SOCKET_CLOSE:{code:8,text:"AMQJSC0008I Socket closed."},MALFORMED_UTF:{code:9,text:"AMQJSC0009E Malformed UTF data:{0} {1} {2}."},UNSUPPORTED:{code:10,text:"AMQJSC0010E {0} is not supported by this browser."},INVALID_STATE:{code:11,text:"AMQJSC0011E Invalid state {0}."},INVALID_TYPE:{code:12,text:"AMQJSC0012E Invalid type {0} for {1}."},INVALID_ARGUMENT:{code:13,text:"AMQJSC0013E Invalid argument {0} for {1}."},UNSUPPORTED_OPERATION:{code:14,text:"AMQJSC0014E Unsupported operation."},INVALID_STORED_DATA:{code:15,text:"AMQJSC0015E Invalid data in local storage key={0} value={1}."},INVALID_MQTT_MESSAGE_TYPE:{code:16,text:"AMQJSC0016E Invalid MQTT message type {0}."},MALFORMED_UNICODE:{code:17,text:"AMQJSC0017E Malformed Unicode string:{0} {1}."}};
var MQTT_CONNECT=1,MQTT_CONNACK=2,MQTT_PUBLISH=3,MQTT_PUBACK=4,MQTT_PUBREC=5,MQTT_PUBREL=6,MQTT_PUBCOMP=7,MQTT_SUBSCRIBE=8,MQTT_SUBACK=9,MQTT_UNSUBSCRIBE=10,MQTT_UNSUBACK=11,MQTT_PINGREQ=12,MQTT_PINGRESP=13,MQTT_DISCONNECT=14;
var CONNACK_RC={0:"Connection Accepted",1:"Connection Refused: unacceptable protocol version",2:"Connection Refused: identifier rejected",3:"Connection Refused: server unavailable",4:"Connection Refused: bad user name or password",5:"Connection Refused: not authorized"};

function Message(payload){
    if(typeof payload==="string"){
        var buffer=new ArrayBuffer(payload.length*2);
        var bufferView=new Uint8Array(buffer);
        for(var i=0;i<payload.length;i++)bufferView[i]=payload.charCodeAt(i);
        this._buffer=buffer;
        this._arrayBuffer=buffer;
    }else if(payload instanceof ArrayBuffer){
        this._buffer=payload;
        this._arrayBuffer=payload;
    }else{
        throw new Error("Invalid payload type");
    }
    this.payloadBytes=this._arrayBuffer;
}
Object.defineProperty(Message.prototype,"payloadString",{get:function(){
    var buffer=new Uint8Array(this._arrayBuffer);
    var str="";
    for(var i=0;i<buffer.length;i++)str+=String.fromCharCode(buffer[i]);
    return str;
}});
Object.defineProperty(Message.prototype,"destinationName",{get:function(){return this._destinationName;},set:function(v){this._destinationName=v;}});
Object.defineProperty(Message.prototype,"qos",{get:function(){return this._qos||0;},set:function(v){this._qos=v;}});
Object.defineProperty(Message.prototype,"retained",{get:function(){return this._retained||false;},set:function(v){this._retained=v;}});

function encodeMBI(n){var r=[];do{var d=n%128;n>>=7;if(n>0)d|=0x80;r.push(d);}while(n>0);return r;}
function encodeTwoByteInt(n){return[n>>8,n&0xFF];}

function encodeUTF8(str){
    var encoded=[];
    for(var i=0;i<str.length;i++){
        var c=str.charCodeAt(i);
        if(c<128)encoded.push(c);
        else if(c<2048){encoded.push((c>>6)|192);encoded.push((c&63)|128);}
        else{encoded.push((c>>12)|224);encoded.push(((c>>6)&63)|128);encoded.push((c&63)|128);}
    }
    return encoded;
}

function writeUTF8(str){
    var encoded=encodeUTF8(str);
    return encodeTwoByteInt(encoded.length).concat(encoded);
}

function decodeUTF8(buffer,offset,length){
    var str="";
    var end=offset+length;
    for(var i=offset;i<end;i++){
        var c=buffer[i];
        if(c<128)str+=String.fromCharCode(c);
        else if((c&224)===192){str+=String.fromCharCode(((c&31)<<6)|(buffer[++i]&63));}
        else{str+=String.fromCharCode(((c&15)<<12)|((buffer[++i]&63)<<6)|(buffer[++i]&63));}
    }
    return str;
}

function Client(host,port,path,clientId){
    if(typeof path==="string"&&typeof clientId==="undefined"){clientId=path;path="/mqtt";}
    if(typeof clientId==="undefined"){clientId=path;path="/mqtt";}
    if(!clientId||clientId.length===0)throw new Error("clientId must be provided");
    this._host=host;
    this._port=port;
    this._path=path||"/mqtt";
    this._clientId=clientId;
    this._connected=false;
    this._socket=null;
    this._msgId=0;
    this._connectOptions={};
    this.onConnectionLost=null;
    this.onMessageArrived=null;
    this.onMessageDelivered=null;
}

Client.prototype.connect=function(opts){
    opts=opts||{};
    this._connectOptions=opts;
    var self=this;
    var uri="ws://"+this._host+":"+this._port+this._path;
    try{
        this._socket=new WebSocket(uri,["mqtt"]);
        this._socket.binaryType="arraybuffer";
    }catch(e){
        if(opts.onFailure)opts.onFailure({errorMessage:e.message});
        return;
    }
    var timeout=setTimeout(function(){
        if(!self._connected){
            self._socket.close();
            if(opts.onFailure)opts.onFailure({errorMessage:"Connection timed out"});
        }
    },(opts.timeout||30)*1000);

    this._socket.onopen=function(){
        // Send CONNECT packet
        var payload=[];
        // Protocol name
        payload=payload.concat(writeUTF8("MQTT"));
        // Protocol level (4 = MQTT 3.1.1)
        payload.push(4);
        // Connect flags
        var flags=2; // cleanSession
        if(opts.userName)flags|=128;
        if(opts.password)flags|=64;
        payload.push(flags);
        // KeepAlive
        var keepAlive=opts.keepAliveInterval||60;
        payload=payload.concat(encodeTwoByteInt(keepAlive));
        // Client ID
        payload=payload.concat(writeUTF8(self._clientId));
        if(opts.userName)payload=payload.concat(writeUTF8(opts.userName));
        if(opts.password)payload=payload.concat(writeUTF8(opts.password));
        // Fixed header
        var fixed=[MQTT_CONNECT<<4].concat(encodeMBI(payload.length));
        var packet=new Uint8Array(fixed.concat(payload));
        self._socket.send(packet.buffer);
    };

    this._socket.onmessage=function(event){
        var buffer=new Uint8Array(event.data);
        var type=(buffer[0]>>4)&0x0F;
        if(type===MQTT_CONNACK){
            clearTimeout(timeout);
            var rc=buffer[3];
            if(rc===0){
                self._connected=true;
                if(opts.onSuccess)opts.onSuccess({});
                // Start keepalive ping
                self._pingInterval=setInterval(function(){
                    if(self._connected&&self._socket.readyState===1){
                        var ping=new Uint8Array([MQTT_PINGREQ<<4,0]);
                        self._socket.send(ping.buffer);
                    }
                },(keepAlive*1000*0.75));
            }else{
                if(opts.onFailure)opts.onFailure({errorMessage:CONNACK_RC[rc]||"Connection refused: "+rc});
            }
        }else if(type===MQTT_PUBLISH){
            var dup=(buffer[0]&0x08)>>3;
            var qos=(buffer[0]&0x06)>>1;
            var pos=1;
            // Remaining length
            var multiplier=1,value=0,digit;
            do{digit=buffer[pos++];value+=(digit&127)*multiplier;multiplier*=128;}while((digit&128)!==0);
            // Topic
            var topicLen=(buffer[pos]<<8)|buffer[pos+1];pos+=2;
            var topic=decodeUTF8(buffer,pos,topicLen);pos+=topicLen;
            if(qos>0)pos+=2; // msgId
            // Payload
            var payloadLen=value-(2+topicLen+(qos>0?2:0));
            var msg=new Message(event.data.slice(pos,pos+payloadLen));
            msg.destinationName=topic;
            msg.qos=qos;
            if(self.onMessageArrived)self.onMessageArrived(msg);
        }else if(type===MQTT_SUBACK||type===MQTT_UNSUBACK||type===MQTT_PUBACK||type===MQTT_PINGRESP){
            // ACKs - no action needed for QoS 0
        }
    };

    this._socket.onerror=function(e){
        self._connected=false;
        if(opts.onFailure)opts.onFailure({errorMessage:"WebSocket error"});
    };

    this._socket.onclose=function(e){
        self._connected=false;
        clearInterval(self._pingInterval);
        if(self.onConnectionLost)self.onConnectionLost({errorCode:e.code,errorMessage:e.reason||"Connection closed"});
    };
};

Client.prototype.subscribe=function(topic,opts){
    if(!this._connected)return;
    opts=opts||{};
    var qos=opts.qos||0;
    this._msgId=(this._msgId+1)&0xFFFF;
    var payload=[];
    payload=payload.concat(encodeTwoByteInt(this._msgId));
    payload=payload.concat(writeUTF8(topic));
    payload.push(qos);
    var fixed=[(MQTT_SUBSCRIBE<<4)|2].concat(encodeMBI(payload.length));
    var packet=new Uint8Array(fixed.concat(payload));
    this._socket.send(packet.buffer);
};

Client.prototype.unsubscribe=function(topic){
    if(!this._connected)return;
    this._msgId=(this._msgId+1)&0xFFFF;
    var payload=[];
    payload=payload.concat(encodeTwoByteInt(this._msgId));
    payload=payload.concat(writeUTF8(topic));
    var fixed=[(MQTT_UNSUBSCRIBE<<4)|2].concat(encodeMBI(payload.length));
    var packet=new Uint8Array(fixed.concat(payload));
    this._socket.send(packet.buffer);
};

Client.prototype.send=function(topic,payload,qos,retained){
    if(!this._connected)return;
    var msg;
    if(topic instanceof Message){msg=topic;}
    else{msg=new Message(payload||"");msg.destinationName=topic;msg.qos=qos||0;msg.retained=retained||false;}
    var topicBytes=writeUTF8(msg.destinationName);
    var payloadArray=new Uint8Array(msg.payloadBytes||msg._arrayBuffer);
    var payloadBytes=Array.from(payloadArray);
    var varHeader=topicBytes;
    if(msg.qos>0){this._msgId=(this._msgId+1)&0xFFFF;varHeader=varHeader.concat(encodeTwoByteInt(this._msgId));}
    var all=varHeader.concat(payloadBytes);
    var flags=(msg.retained?1:0)|((msg.qos&3)<<1)|((msg.qos>0?0:0)<<3);
    var fixed=[(MQTT_PUBLISH<<4)|flags].concat(encodeMBI(all.length));
    var packet=new Uint8Array(fixed.concat(all));
    this._socket.send(packet.buffer);
};

Client.prototype.disconnect=function(){
    if(!this._connected)return;
    clearInterval(this._pingInterval);
    var packet=new Uint8Array([MQTT_DISCONNECT<<4,0]);
    this._socket.send(packet.buffer);
    this._socket.close();
    this._connected=false;
};

return{Client:Client,Message:Message};
})();
